'use strict';
(()=>{
 const q=s=>document.querySelector(s),key='bonga-suppliers-v1',types=['White label','Dropshipping / print on demand','Outsourced manufacturing','Materials / components'],stages=['To research','Contacted','Sample requested','Sample approved','Active supplier','Paused'];
 const clean=(v,n=500)=>typeof v==='string'?v.trim().slice(0,n):'';
 const link=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}};
 const number=v=>v===''||v===null||v===undefined?null:Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null;
 const seeds=[{id:'printful',name:'Printful',type:types[1],website:'https://www.printful.com/sell-clothes-online',notes:'White-label apparel and print-on-demand candidate. Confirm product, South Africa delivery, branding, landed cost and returns before ordering.'},{id:'printify',name:'Printify',type:types[1],website:'https://printify.com/print-on-demand/',notes:'Print-provider network candidate. Compare individual providers, quality, branding options and destination shipping.'},{id:'gelato',name:'Gelato',type:types[1],website:'https://support.gelato.com/en/articles/8996114-do-you-offer-a-white-labeled-solution',notes:'White-label fulfillment candidate. Confirm garment availability, shipping destination and branding options.'},{id:'monatic',name:'Monatic',type:types[0],website:'https://monatic.co.za/white-label/',notes:'South African white/private-label menswear production candidate. Request sample, MOQ, terms and a quote.'}].map(s=>({...s,portal:'',contact:'',stage:stages[0],moq:'',delivery:'',returns:'',checked:'2026-10-07'}));
 let data={suppliers:seeds,products:[]},editing='',productEditing='';
 function normalize(d){if(!d||!Array.isArray(d.suppliers)||!Array.isArray(d.products))throw Error('Choose a supplier workspace backup.');return {suppliers:d.suppliers.slice(0,200).filter(x=>x&&clean(x.name)).map(s=>({id:clean(s.id,100)||crypto.randomUUID(),name:clean(s.name,100),type:types.includes(s.type)?s.type:types[2],website:link(s.website),portal:link(s.portal),contact:clean(s.contact,200),stage:stages.includes(s.stage)?s.stage:stages[0],moq:clean(s.moq,100),delivery:clean(s.delivery,200),returns:clean(s.returns,300),notes:clean(s.notes,1000),checked:clean(s.checked,30)})),products:d.products.slice(0,300).filter(x=>x&&clean(x.name)).map(p=>({id:clean(p.id,100)||crypto.randomUUID(),name:clean(p.name,150),supplier:clean(p.supplier,100),url:link(p.url),cost:number(p.cost),shipping:number(p.shipping),other:number(p.other),price:number(p.price),notes:clean(p.notes,500)}))};}
 try{const saved=JSON.parse(localStorage.getItem(key));if(saved)data=normalize(saved);}catch{}
 function status(t){q('#supplier-status').textContent=t;}
 function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
 function btn(t,f){const b=el('button',t);b.type='button';b.className='button secondary';b.addEventListener('click',f);return b;}
 function anchor(t,u){const a=el('a',t);a.href=u;a.target='_blank';a.rel='noopener noreferrer';return a;}
 function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{status('This browser could not save. Export a backup before leaving.');}render();}
 function resetSupplier(){editing='';q('#supplier-form').reset();q('#supplier-save').textContent='Save supplier';}
 function resetProduct(){productEditing='';q('#supplier-product-form').reset();q('#supplier-product-save').textContent='Save product';}
 function render(){
  q('#supplier-records').replaceChildren(...data.suppliers.map(s=>{const n=el('article');n.className='business-record';n.append(el('h3',s.name),el('p',s.type+' · '+s.stage),el('p','Account/API connection: not configured'),el('p',s.notes),el('p','MOQ: '+(s.moq||'Unknown')+' · Delivery: '+(s.delivery||'Unknown')),el('p','Returns: '+(s.returns||'Unknown')));if(s.website)n.append(anchor('Source / supplier website',s.website));if(s.portal)n.append(anchor('Open my supplier portal',s.portal));n.append(btn('Edit supplier',()=>{editing=s.id;for(const field of ['name','type','website','portal','contact','stage','moq','delivery','returns','notes'])q('#supplier-'+field).value=s[field]||'';q('#supplier-save').textContent='Save changes';q('#supplier-form').scrollIntoView({behavior:'smooth'});}),btn('Remove',()=>{data.suppliers=data.suppliers.filter(x=>x.id!==s.id);data.products=data.products.map(p=>p.supplier===s.id?{...p,supplier:''}:p);if(editing===s.id)resetSupplier();save();status('Supplier removed; product records retained for review.');}));return n;}));
  const selected=q('#supplier-product-partner').value;q('#supplier-product-partner').replaceChildren();const empty=el('option','Choose supplier');empty.value='';q('#supplier-product-partner').append(empty);data.suppliers.forEach(s=>{const o=el('option',s.name);o.value=s.id;q('#supplier-product-partner').append(o);});q('#supplier-product-partner').value=selected;
  q('#supplier-products').replaceChildren(...data.products.map(p=>{const n=el('article');n.className='business-record';const s=data.suppliers.find(s=>s.id===p.supplier);const complete=[p.cost,p.shipping,p.other,p.price].every(x=>x!==null);const landed=complete?p.cost+p.shipping+p.other:null;const gross=complete?p.price-landed:null;n.append(el('h3',p.name),el('p','Supplier: '+(s?.name||'Needs supplier assignment')),el('p',complete?'Estimated landed cost R'+landed.toFixed(2)+' · Gross contribution R'+gross.toFixed(2):'Add all costs and selling price to calculate contribution.'),el('p','Manual ZAR estimates. Other costs should include applicable duty, taxes and fees. This is not a quote or net profit.'),el('p',p.notes));if(p.url)n.append(anchor('View supplier product',p.url));n.append(btn('Edit product',()=>{productEditing=p.id;q('#supplier-product-partner').value=p.supplier;for(const f of ['name','url','cost','shipping','other','price','notes'])q('#supplier-product-'+f).value=p[f]??'';q('#supplier-product-save').textContent='Save product changes';q('#supplier-product-form').scrollIntoView({behavior:'smooth'});}),btn('Remove',()=>{data.products=data.products.filter(x=>x.id!==p.id);if(productEditing===p.id)resetProduct();save();}));return n;}));
  if(!data.products.length)q('#supplier-products').append(el('p','No outsourced products yet. Add a real product and supplier quote when you have one.'));
 }
 types.forEach(t=>{const o=el('option',t);o.value=t;q('#supplier-type').append(o);});stages.forEach(t=>{const o=el('option',t);o.value=t;q('#supplier-stage').append(o);});
 q('#supplier-form').addEventListener('submit',e=>{e.preventDefault();const s={id:editing||crypto.randomUUID(),checked:new Date().toISOString().slice(0,10)};for(const f of ['name','type','website','portal','contact','stage','moq','delivery','returns','notes'])s[f]=clean(q('#supplier-'+f).value, f==='notes'?1000:500);for(const f of ['website','portal']){if(s[f]&&!link(s[f])){status('Use a valid HTTP(S) supplier link.');return;}s[f]=link(s[f]);}const i=data.suppliers.findIndex(x=>x.id===editing);if(i>=0)data.suppliers[i]=s;else data.suppliers.push(s);resetSupplier();save();status('Supplier saved. No external account was connected and no order was sent.');});
 q('#supplier-cancel').addEventListener('click',resetSupplier);
 q('#supplier-product-form').addEventListener('submit',e=>{e.preventDefault();const p={id:productEditing||crypto.randomUUID(),supplier:q('#supplier-product-partner').value};for(const f of ['name','url','notes'])p[f]=clean(q('#supplier-product-'+f).value);if(p.url&&!link(p.url)){status('Use a valid supplier product link.');return;}p.url=link(p.url);for(const f of ['cost','shipping','other','price'])p[f]=number(q('#supplier-product-'+f).value);const i=data.products.findIndex(x=>x.id===productEditing);if(i>=0)data.products[i]=p;else data.products.push(p);resetProduct();save();status('Product saved as a private sourcing record.');});
 q('#supplier-product-cancel').addEventListener('click',resetProduct);
 q('#supplier-export').addEventListener('click',()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='Bonga-Bhengu-suppliers.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status('Supplier workspace backup exported.');});
 q('#supplier-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('Backup must be under 1 MB.');data=normalize(JSON.parse(await file.text()));resetSupplier();resetProduct();save();status('Supplier backup restored.');}catch(err){status(err.message||'Could not restore backup.');}e.target.value='';});
 render();
})();
